    public function isSameMonth($date = null, $ofSameYear = true)
    {
        $this->lastComparedDate = $this->resolveCarbon($date);
        $this->lastComparisonResult = $this->isSameAs($ofSameYear ? 'Y-m' : 'm', $date);

        return $this->lastComparisonResult;
    }

